            let mut output_buf = Vec::new();
            while let Ok(length) = locked_stdin.read_until(b'\n', &mut buf) {
                if length == 0 {
                    break;
                } else {
                    for &current in buf.iter() {
                        if let Some(kept) = delete_op.translate(current) {
                            output_buf.extend(squeeze_op.translate(kept));
                        }
                    }
                    buffered_stdout.write_all(&output_buf).unwrap();
                }
                buf.clear();
                output_buf.clear();
            }
